export type StoreBrand = 'Carl Ras' | '3Aktive' | 'Meesenburg' | 'Foussier' | 'Lecot';
export type StoreRegion = string;
export type StoreCountry = 'dk' | 'de' | 'fr' | 'be';
export interface StoreSpecialist { name: string; role?: string; photo?: string; email?: string; phone?: string; }

export interface Store {
  id: string;
  name: string;
  brand: StoreBrand;
  country: StoreCountry;
  region?: string;
  address: string;
  zipCity: string;
  lat: number;
  lng: number;
  maps: string;
  /** General store contact line, used by dealer stores that have no named manager. */
  phone?: string;
  email?: string;
  /** Named store manager with a portrait (DK). Optional: dealer stores abroad have none. */
  manager?: { name: string; email: string; phone: string; photo: string };
  /** Optional dedicated STROXX Specialist contact, shown on the store card. */
  specialist?: StoreSpecialist;
  /** [open, close] as decimal clock values from the CMS, e.g. 6.3 = 06:30. Omitted when hours are unknown. */
  monThu?: [number, number];
  fri?: [number, number];
  weekendClosed: boolean;
  festool: boolean;
  sikring: boolean;
  aktive3: boolean;
}

/** 6.3 → "06:30", 16 → "16:00" */
export const clock = (n: number) => {
  const h = Math.floor(n);
  const m = Math.round((n - h) * 100);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

export const hoursLabel = (s: Store) =>
  s.monThu && s.fri
    ? `Mon-Thu ${clock(s.monThu[0])}-${clock(s.monThu[1])} · Fri ${clock(s.fri[0])}-${clock(s.fri[1])}`
    : '';

/** Great-circle distance in km */
export const distanceKm = (aLat: number, aLng: number, bLat: number, bLng: number) => {
  const R = 6371;
  const dLat = ((bLat - aLat) * Math.PI) / 180;
  const dLng = ((bLng - aLng) * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((aLat * Math.PI) / 180) * Math.cos((bLat * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
};

